"""Private document storage. Object paths are generated by the server."""
from pathlib import Path
from urllib.parse import quote
import httpx
from backend.app.config import settings


class StorageService:
    @staticmethod
    def _request(method, path, **kwargs):
        if not settings.SUPABASE_URL or not settings.SUPABASE_SECRET_KEY:
            raise RuntimeError("Configure Supabase storage credentials")
        # apikey supports Supabase server secret keys. No user-controlled URL.
        headers = {"apikey": settings.SUPABASE_SECRET_KEY}
        if settings.SUPABASE_SECRET_KEY.startswith("eyJ"):
            headers["Authorization"] = f"Bearer {settings.SUPABASE_SECRET_KEY}"
        headers.update(kwargs.pop("headers", {}))
        response = httpx.request(method, settings.SUPABASE_URL.rstrip("/") + "/storage/v1/" + path,
                                 headers=headers, timeout=60, **kwargs)
        response.raise_for_status()
        return response

    @classmethod
    def save(cls, key, data, content_type):
        if settings.STORAGE_PROVIDER == "supabase":
            path = f"{settings.SUPABASE_STORAGE_BUCKET}/{key}"
            cls._request("POST", "object/" + quote(path, safe="/"), content=data,
                         headers={"Content-Type": content_type, "x-upsert": "false"})
            return "supabase://" + path
        if settings.STORAGE_PROVIDER != "local":
            raise ValueError("Unknown storage provider")
        path = Path(settings.UPLOAD_DIR) / key
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
        return str(path)

    @classmethod
    def read(cls, location):
        if location.startswith("supabase://"):
            return cls._request("GET", "object/authenticated/" + quote(location[11:], safe="/")).content
        return Path(location).read_bytes()

    @classmethod
    def delete(cls, location):
        if location.startswith("supabase://"):
            bucket, key = location[11:].split("/", 1)
            cls._request("DELETE", "object/" + quote(bucket, safe=""), json={"prefixes": [key]})
        else:
            Path(location).unlink(missing_ok=True)
